#!/usr/bin/env python3
# -*- coding: utf-8 -*-

"""
Automatic installer for:

CTRL-018 — Validator Result Consistency Refactor
Part I — Result Normalization Architecture

Safety guarantees
-----------------
- Modifies only validate_project_control.py.
- Creates a timestamped backup before writing.
- Locates the exact architectural insertion marker.
- Refuses duplicate installation.
- Validates Python syntax before and after writing.
- Restores the backup automatically if verification fails.
- Does not modify YAML or Markdown files.
"""

from __future__ import annotations

import ast
import base64
import shutil
import sys
from datetime import datetime
from pathlib import Path


TARGET_NAME = "validate_project_control.py"
INSTALL_MARKER = "CTRL-018 — VALIDATOR RESULT CONSISTENCY REFACTOR"
INSERTION_MARKER = """# =============================================================================
# VALIDATION STAGE CONTRACT
# =============================================================================
"""

PART_CODE = base64.b64decode(
    ""
).decode("utf-8")


def syntax_check(text: str, filename: str) -> None:
    ast.parse(text, filename=filename)


def main() -> int:
    script_directory = Path(__file__).resolve().parent
    target = script_directory / TARGET_NAME

    if not target.is_file():
        print(
            f"ERROR: File not found: {target}",
            file=sys.stderr,
        )
        return 2

    original = target.read_text(encoding="utf-8")

    if INSTALL_MARKER in original:
        print("NO CHANGES REQUIRED")
        print("CTRL-018 Part I is already installed.")
        return 0

    marker_count = original.count(INSERTION_MARKER)

    if marker_count != 1:
        print(
            "ERROR: Expected exactly one architectural insertion marker; "
            f"found {marker_count}.",
            file=sys.stderr,
        )
        return 3

    required_symbols = (
        "class ValidationFinding:",
        "class StageResult:",
        "class ValidationReport:",
        "class ValidationContext:",
        "class ValidationPipeline:",
    )

    missing_symbols = [
        symbol
        for symbol in required_symbols
        if symbol not in original
    ]

    if missing_symbols:
        print(
            "ERROR: Required validator symbols were not found:",
            file=sys.stderr,
        )
        for symbol in missing_symbols:
            print(f"- {symbol}", file=sys.stderr)
        return 4

    insertion = PART_CODE.rstrip() + "\n\n"

    updated = original.replace(
        INSERTION_MARKER,
        insertion + INSERTION_MARKER,
        1,
    )

    try:
        syntax_check(updated, str(target))
    except SyntaxError as error:
        print("PATCH NOT APPLIED", file=sys.stderr)
        print(
            f"Pre-write syntax verification failed: {error}",
            file=sys.stderr,
        )
        return 5

    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    backup = target.with_name(
        f"{target.name}.bak_ctrl018_part1_{timestamp}"
    )

    try:
        shutil.copy2(target, backup)
        target.write_text(updated, encoding="utf-8")

        verification = target.read_text(encoding="utf-8")
        syntax_check(verification, str(target))

        required_installed_symbols = (
            "class FindingDisposition(str, Enum):",
            "class FindingDecision:",
            "class ResultNormalizationContext:",
            "class FindingNormalizationRule:",
            "class NormalizedStageSnapshot:",
            "class StatusResolver:",
            "class ResultNormalizer:",
            "class ExitCodeResolver:",
            "def build_result_normalizer()",
        )

        missing_installed = [
            symbol
            for symbol in required_installed_symbols
            if symbol not in verification
        ]

        if missing_installed:
            raise RuntimeError(
                "Installed architecture verification failed. "
                "Missing: " + ", ".join(missing_installed)
            )

        if verification.count(INSTALL_MARKER) != 1:
            raise RuntimeError(
                "CTRL-018 Part I installation marker count is invalid."
            )

        if verification.count(INSERTION_MARKER) != 1:
            raise RuntimeError(
                "Validation Stage Contract marker count changed unexpectedly."
            )

    except Exception as error:
        if backup.is_file():
            shutil.copy2(backup, target)

        print("PATCH ROLLED BACK", file=sys.stderr)
        print(f"Reason: {error}", file=sys.stderr)
        return 6

    print("PATCH APPLIED")
    print(f"Updated : {target}")
    print(f"Backup  : {backup}")
    print()
    print("CTRL-018 Part I installed:")
    print("- FindingDisposition")
    print("- FindingDecision")
    print("- ResultNormalizationContext")
    print("- FindingNormalizationRule")
    print("- NormalizationAuditRecord")
    print("- NormalizedStageSnapshot")
    print("- StatusResolver")
    print("- ResultNormalizer")
    print("- ExitCodeResolver")
    print("- build_result_normalizer()")
    print()
    print("Behavioral integration is intentionally deferred")
    print("until CTRL-018 Part II and later parts.")
    print()
    print("No YAML or Markdown files were modified.")
    print()
    print("Next verification command:")
    print("python -m py_compile validate_project_control.py")

    return 0


if __name__ == "__main__":
    raise SystemExit(main())